import{_ as r,I as o,c as s,o as d,j as e,ap as i,a as n,J as p}from"./chunks/framework.BVMg0REN.js";const y=JSON.parse('{"title":"公告存档","description":"","frontmatter":{},"headers":[],"relativePath":"Manual/AnnouncementArchive.md","filePath":"zh/Manual/AnnouncementArchive.md","lastUpdated":1780998854000}'),l={name:"Manual/AnnouncementArchive.md"},c={id:"公告存档",tabindex:"-1"};function m(h,a,u,g,_,M){const t=o("Badge");return d(),s("div",null,[e("h1",c,[a[0]||(a[0]=n("公告存档")),p(t,{type:"info",text:"公告"}),a[1]||(a[1]=n()),a[2]||(a[2]=e("a",{class:"header-anchor",href:"#公告存档","aria-label":"Permalink to “公告存档”"},"​",-1))]),a[3]||(a[3]=i('<h2 id="版本迭代公告-预告-需要安装新运行库" tabindex="-1"><strong>版本迭代公告（预告：需要<u>安装新运行库</u>）</strong> <a class="header-anchor" href="#版本迭代公告-预告-需要安装新运行库" aria-label="Permalink to “版本迭代公告（预告：需要安装新运行库）”">​</a></h2><details><summary>详细内容</summary> 11-12月， MaaYuan 所依赖的底层识图&amp;触控框架进行了大版本更新，很多功能会受到影响，因此先发布一个全旧稳定（？）版，方便大家顺利地月底赶作业 &amp; 月初打洞窟。开发组这边正在闭关进行新框架的适配和重构，争取让 MaaYuan 借此机会脱胎换骨一下。 <p>v2.0.0版本起将需要 <strong>.NET 10</strong> 及以上运行库（原为 .NET 8）才能正常运行。</p><ul><li>自动更新脚本已配置在完整包内，解压后<strong>双击</strong>文件夹内的 （Win 系统）<code>DependencySetup_依赖库安装_win.bat</code> 或 （Mac 系统） <code>DependencySetup_依赖库安装_mac.sh</code> ，尝试自动安装新的运行库。安装完成后可能会提醒<strong>需要重启电脑</strong>，请务必重启。</li><li>如自动安装过程中出现问题，请访问<a href="https://dotnet.microsoft.com/zh-cn/download/dotnet/10.0" target="_blank" rel="noreferrer">官方下载页面</a>，并在页面中找到<code>.NET 桌面运行时 10.0.0 - Windows - 安装程序 - x64</code>或 <code>.NET 运行时 10.0.0 - MacOS - 安装程序</code>（M 芯片选择 <code>Arm64</code> 版、Intel 芯片选择 <code>x64</code> 版）。手动下载并双击<strong>安装</strong>，安装完成后可能会提醒<strong>需要重启电脑</strong>，请务必重启。</li></ul></details><h2 id="全新作业站-maayuan-share-现已上线" tabindex="-1"><strong>全新作业站 MaaYuan Share 现已上线</strong> <a class="header-anchor" href="#全新作业站-maayuan-share-现已上线" aria-label="Permalink to “全新作业站 MaaYuan Share 现已上线”">​</a></h2><details><summary>详细内容</summary> 访问 [MaaYuan Share 作业站](https://share.maayuan.top/) 可获得神秘代码，启动 `MaaYuan` 后，进入 **抄作业专属界面** 使用神秘代码即可一键导入对应作业文件。 作业编辑器 V2 - 新增类表格视图（类似**辟雍学府-操作记录仪**的编辑模式），编写作业更方便。 支持录入密探、星盘、攻击力/血量 等信息，还可只看包含/排除指定密探的作业，帮您快速筛选最合适的作业。 </details><h2 id="群宣-我们有2k人大群啦" tabindex="-1"><strong>群宣 我们有2K人大群啦！</strong> <a class="header-anchor" href="#群宣-我们有2k人大群啦" aria-label="Permalink to “群宣 我们有2K人大群啦！”">​</a></h2><details><summary>详细内容</summary> 经过各种白嫖硬蹭的努力，我们终于取得了2K人大群的资格，不再受限人数到达500就不能修改公告，只能清除潜水人员的情况了（但还是会以年为单位清除长期潜水的群友，如每年6月清理截止本年1月1日前未发言过群友，习惯潜水的群友可以蹲频道，那边不会清理） <p>1️⃣<strong>Maa鸢常驻交流群863288153</strong></p><p>本群为Maa鸢官方群，群里禁止起任何节奏，请和谐友善交流，群内属性复杂，请专注与MaaYuan相关交流，非MaaYuan相关引起纠纷争论，会将双方都移出群。</p><p>2️⃣<strong>Maa鸢作业交流群1055262891</strong></p><p>本群仅限作业制作者加入，需要提供至少2份上传作业站的作业内容供管理员审核。</p><p>3️⃣<strong>Maa鸢活动限时交流群587118812</strong></p><p>本群仅在大型肉鸽活动因大量新玩家加入时开放玩家交流互助，或发布内测功能需要人员测试时开放反馈维护。其他时间会关闭入口并且全时段禁言。</p><p>4️⃣<strong>Maa鸢程序交流群1060902378</strong></p><p>本群仅限程序老师加入，欢迎老师们提交pr共同建设MaaYuan ！！</p></details><h2 id="招募-程序组长期招募" tabindex="-1">招募（程序组长期招募） <a class="header-anchor" href="#招募-程序组长期招募" aria-label="Permalink to “招募（程序组长期招募）”">​</a></h2><details><summary>详细内容</summary> 麻圆的岗位需要用爱发电，我们无法支付任何薪酬，私密马赛 以下招募除程序老师外，均优先可以日常摸鱼电脑的社畜 如果因为工作繁忙无法兼顾可以随时提出退出，期待与你再次相遇 <p>1.程序老师 共同维护麻圆本体及延伸功能的程序员老师，需要熟练掌握 Python，详细请查阅【开发手册】</p><p>2.文档维护组 熟练使用Word、飞书、Typora等软件，有文字编辑、排版制作、网页编辑能力，没有的话就需要有一定的AI使用经验。 主要工作内容维护本网站内文本。</p><p>3.作业站维护组 闲暇时间长，会经常逛网站。 主要工作内容维护作业站内发布的作业及更新关卡等，协助作业老师补全关联信息资料。</p><p>4.频道管理组 喜欢水贴，能帮助回复频道内的答疑。 主要工作内容，管理频道，及协助程序老师管理反馈信息等。</p></details>',8))])}const A=r(l,[["render",m]]);export{y as __pageData,A as default};
